#!/usr/bin/env python3
"""Validate the TG-4U streaming-heap integration and permanent regressions."""
from __future__ import annotations
import argparse,csv,hashlib,json,platform,statistics,subprocess,sys,time,tracemalloc
from collections import Counter
from pathlib import Path

from matmul_inspector.tensor_game_bounded_residual import bounded_residual_candidates,bounded_residual_candidates_memory_efficient,coarse_pair_scores,coarse_pair_scores_streaming,create_residual_candidate_provider
from matmul_inspector.tensor_game_heldout_bounded_search import divergence_rows,paired_outcome,run_trial
from matmul_inspector.tensor_game_search_calibration import ExhaustiveResidualPolicy

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write_json(p,x):p.write_text(json.dumps(x,indent=2,sort_keys=True)+"\n")
def write_csv(p,rows):
 rows=list(rows)
 with p.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def pct(v,p):v=sorted(v);x=(len(v)-1)*p;i=int(x);return v[i] if i==len(v)-1 else v[i]*(i+1-x)+v[i+1]*(x-i)
def states():
 labels=[json.loads(x) for x in Path('artifacts/tensor-game/tg4i-coverage-training-v1/training_labels.jsonl').read_text().splitlines() if x];result=[('tg4q',x['state_id'],x['residual']) for x in labels if x['split']=='validation']
 manifest=json.loads(Path('artifacts/tensor-game/tg4s-provider-integration-v1/regression_targets.json').read_text());result += [('tg4s',x['target_id'],x['target']) for x in manifest['targets']]
 zero=[[[0]*4 for _ in range(4)] for _ in range(4)];dense=[[[((i*7+j*3+k)%3)-1 for k in range(4)] for j in range(4)] for i in range(4)];repeated=[[[2 if i==j==k else 0 for k in range(4)] for j in range(4)] for i in range(4)];tie=[[[1 if i==j==k else 0 for k in range(4)] for j in range(4)] for i in range(4)];near=[[[1 if (i+j+k)%5==0 else -1 if (i*3+j+k)%7==0 else 0 for k in range(4)] for j in range(4)] for i in range(4)]
 return result+[('synthetic','zero',zero),('synthetic','dense',dense),('synthetic','repeated',repeated),('synthetic','tie_heavy',tie),('synthetic','near_tie',near)]

def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,default=Path('artifacts/tensor-game/tg4u-streaming-integration-v1'));a=p.parse_args()
 if a.output.exists():raise FileExistsError(a.output)
 a.output.mkdir(parents=True);manifest_path=Path('artifacts/tensor-game/tg4s-provider-integration-v1/regression_targets.json');spec_path=Path('artifacts/tensor-game/tg4s-provider-integration-v1/evaluation_spec.json');manifest=json.loads(manifest_path.read_text());spec=json.loads(spec_path.read_text())
 contract="""# `bounded_128` behavioral contract\n\n- Coarse score: exact integer common-denominator representation of `sum(d_k^2)/q`.\n- Selection: best 128 `(u,v)` pairs ordered by descending coarse score, then lexicographic `u`, then `v`.\n- Heap ties: the heap root reverses `u,v` so the worst retained tie is evicted; retained pairs are finally sorted with the reference key.\n- `w`: each coefficient is the allowed integer nearest to `d_k/q` using existing deterministic ties.\n- Final score: exact integer expansion of `||R-u⊗v⊗w||²`.\n- Actions: legal coefficients, sign canonicalization, canonical deduplication, then score/`u`/`v`/`w` ordering.\n- Output: at most 12 candidates with uniform positive priors through the policy adapter.\n- Metadata: provider identifier remains `bounded_128`. Exhaustive remains the factory and CLI default.\n- Search: unchanged `SampledMCTS`, value evaluation, transitions, and exact-success predicate.\n\n`bounded_residual_candidates` is retained as the internal full-list differential oracle. The integrated policy calls `bounded_residual_candidates_memory_efficient`.\n""";(a.output/'behavioral_contract.md').write_text(contract)
 diff=[]
 for source,identifier,residual in states():
  op=coarse_pair_scores(residual)[:128];np=coarse_pair_scores_streaming(residual,128);old,_=bounded_residual_candidates(residual,128,12);new,_=bounded_residual_candidates_memory_efficient(residual,128,12)
  diff.append({'source':source,'state_id':identifier,'pairs_equal':op==np,'rows_equal':old==new,'candidate_count':len(old),'candidate_ids':';'.join(x['action_id'] for x in old),'scores':';'.join(str(x['score']) for x in old)})
 write_csv(a.output/'differential_results.csv',diff)
 if not all(x['pairs_equal'] and x['rows_equal'] for x in diff):raise RuntimeError('integration differential failure')
 validation={'git':{'branch':subprocess.check_output(['git','branch','--show-current'],text=True).strip(),'commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'working_tree_clean':not bool(subprocess.check_output(['git','status','--porcelain'],text=True).strip())},'environment':{'python':sys.version.split()[0],'platform':platform.platform(),'device':'cpu'},'tg4s_manifest_sha256':sha(manifest_path),'tg4s_spec_sha256':sha(spec_path),'expected_tg4s_manifest_sha256':(manifest_path.with_suffix('.sha256').read_text().split()[0]),'expected_tg4s_spec_sha256':(spec_path.with_suffix('.sha256').read_text().split()[0]),'default_provider_type':type(create_residual_candidate_provider()).__name__,'bounded_provider_type':type(create_residual_candidate_provider('bounded_128')).__name__,'default_is_exhaustive':isinstance(create_residual_candidate_provider(),ExhaustiveResidualPolicy),'provider_identifier':create_residual_candidate_provider('bounded_128').name,'cli_default':'exhaustive','new_dependencies':[],'production_mcts_modified':False}
 validation['frozen_hashes_valid']=validation['tg4s_manifest_sha256']==validation['expected_tg4s_manifest_sha256'] and validation['tg4s_spec_sha256']==validation['expected_tg4s_spec_sha256'];write_json(a.output/'integration_validation.json',validation)
 bench=states()[:8];lat=[]
 for _,_,residual in bench[:2]:bounded_residual_candidates(residual,128,12);bounded_residual_candidates_memory_efficient(residual,128,12)
 for si,(_,identifier,residual) in enumerate(bench):
  for repeat in range(3):
   order=('reference','integrated') if (si+repeat)%2==0 else ('integrated','reference')
   for oi,name in enumerate(order):
    fn=bounded_residual_candidates if name=='reference' else bounded_residual_candidates_memory_efficient;start=time.perf_counter_ns();rows,audit=fn(residual,128,12);lat.append({'state_id':identifier,'repeat':repeat,'execution_order':oi,'implementation':name,'candidate_ms':(time.perf_counter_ns()-start)/1e6,'selection_ms':audit['coarse_scoring_ms'],'candidate_count':len(rows)})
 write_csv(a.output/'performance_smoke.csv',lat)
 memory=[]
 for _,identifier,residual in bench:
  for name,fn in (('reference',bounded_residual_candidates),('integrated',bounded_residual_candidates_memory_efficient)):
   tracemalloc.start();rows,_=fn(residual,128,12);current,peak=tracemalloc.get_traced_memory();tracemalloc.stop();memory.append({'state_id':identifier,'implementation':name,'python_peak_bytes':peak,'python_retained_bytes':current,'candidate_count':len(rows)})
 write_csv(a.output/'memory_smoke.csv',memory)
 results=[];traces={}
 for ti,target in enumerate(manifest['targets']):
  for si,seed in enumerate(spec['seeds']):
   order=('bounded_128','bounded_128_integrated') if (ti+si)%2==0 else ('bounded_128_integrated','bounded_128')
   for oi,name in enumerate(order):row,trace=run_trial(target,name,seed,spec);row['execution_order']=oi;results.append(row);traces[target['target_id'],seed,name]=trace;write_csv(a.output/'search_regression.csv',results)
 pairs=[];divergences=0
 for target in manifest['targets']:
  for seed in spec['seeds']:
   old=next(x for x in results if x['target_id']==target['target_id'] and x['seed']==seed and x['provider']=='bounded_128');new=next(x for x in results if x['target_id']==target['target_id'] and x['seed']==seed and x['provider']=='bounded_128_integrated');pair=paired_outcome(old,new);matched=divergence_rows(traces[target['target_id'],seed,'bounded_128'],traces[target['target_id'],seed,'bounded_128_integrated']);different=sum(not x['same_order'] for x in matched);divergences+=different;pair.update({'matched_states':len(matched),'candidate_divergences':different,'simulations_equal':old['simulations_completed']==new['simulations_completed'],'expansions_equal':old['expanded_nodes']==new['expanded_nodes'],'proposal_calls_equal':old['candidate_generation_calls']==new['candidate_generation_calls']});pairs.append(pair)
 original=[x for x in lat if x['implementation']=='reference'];integrated=[x for x in lat if x['implementation']=='integrated'];om=[x for x in memory if x['implementation']=='reference'];im=[x for x in memory if x['implementation']=='integrated'];old_search=[x for x in results if x['provider']=='bounded_128'];new_search=[x for x in results if x['provider']=='bounded_128_integrated']
 summary={'integration':validation,'differential_states':len(diff),'all_differential_exact':all(x['rows_equal'] and x['pairs_equal'] for x in diff),'search_trials':len(results),'paired_outcomes':dict(Counter(x['outcome'] for x in pairs)),'candidate_divergences':divergences,'all_trajectory_fields_equal':all(x['simulations_equal'] and x['expansions_equal'] and x['proposal_calls_equal'] for x in pairs),'performance':{'reference_mean_candidate_ms':statistics.mean(x['candidate_ms'] for x in original),'integrated_mean_candidate_ms':statistics.mean(x['candidate_ms'] for x in integrated),'reference_p95_candidate_ms':pct([x['candidate_ms'] for x in original],.95),'integrated_p95_candidate_ms':pct([x['candidate_ms'] for x in integrated],.95),'reference_mean_search_seconds':statistics.mean(x['search_wall_seconds'] for x in old_search),'integrated_mean_search_seconds':statistics.mean(x['search_wall_seconds'] for x in new_search),'reference_proposal_calls':sum(x['candidate_generation_calls'] for x in old_search),'integrated_proposal_calls':sum(x['candidate_generation_calls'] for x in new_search)},'memory':{'reference_mean_peak_bytes':statistics.mean(x['python_peak_bytes'] for x in om),'integrated_mean_peak_bytes':statistics.mean(x['python_peak_bytes'] for x in im),'reference_mean_retained_bytes':statistics.mean(x['python_retained_bytes'] for x in om),'integrated_mean_retained_bytes':statistics.mean(x['python_retained_bytes'] for x in im)},'default_provider':'exhaustive','tg4v_recommendation':'Run a preregistered default-provider decision study with dense, repeated-term, and larger independent target coverage; do not change the default automatically.'};write_json(a.output/'summary.json',summary);write_csv(a.output/'paired_outcomes.csv',pairs)
 perf=summary['performance'];mem=summary['memory'];ratio=mem['reference_mean_peak_bytes']/mem['integrated_mean_peak_bytes'];speed=perf['reference_mean_candidate_ms']/perf['integrated_mean_candidate_ms'];search=perf['reference_mean_search_seconds']/perf['integrated_mean_search_seconds']
 report=f"""# TG-4U streaming heap integration\n\n## Result\n\nThe opt-in `bounded_128` policy now uses the streaming heap. Exhaustive remains default. All {len(diff)} permanent differential fixtures matched the full-list oracle exactly. The frozen TG-4S replay produced {summary['paired_outcomes']}, zero candidate divergences, and identical simulations, expansions, and proposal calls.\n\n## Integration evidence\n\nThe public provider identifier and CLI flag are unchanged. `bounded_residual_candidates` remains the internal reference oracle. The integrated adapter calls `bounded_residual_candidates_memory_efficient`, retaining 128 rather than 6,400 coarse records. No dependency, MCTS, transition, scoring, or success-predicate change was made.\n\n## Smoke measurements\n\n| Metric | Reference | Integrated |\n|---|---:|---:|\n| Mean candidate latency | {perf['reference_mean_candidate_ms']:.2f} ms | {perf['integrated_mean_candidate_ms']:.2f} ms |\n| p95 candidate latency | {perf['reference_p95_candidate_ms']:.2f} ms | {perf['integrated_p95_candidate_ms']:.2f} ms |\n| Mean traced peak | {mem['reference_mean_peak_bytes']/1e6:.2f} MB | {mem['integrated_mean_peak_bytes']/1e6:.2f} MB |\n| Mean retained | {mem['reference_mean_retained_bytes']/1e6:.3f} MB | {mem['integrated_mean_retained_bytes']/1e6:.3f} MB |\n| Mean search latency | {perf['reference_mean_search_seconds']:.4f} s | {perf['integrated_mean_search_seconds']:.4f} s |\n\nPeak traced memory improved {ratio:.1f}×. Candidate timing ratio was {speed:.2f}× and same-session search ratio was {search:.2f}×. This is a smoke regression, not a new performance claim.\n\n## Answers\n\n1. Yes. The opt-in provider adapter calls the streaming heap implementation.\n2. Yes. Factory and CLI defaults remain exhaustive.\n3. Yes, across all {len(diff)} permanent fixtures.\n4. Yes. All 48 paired search trajectories and discovery outcomes were preserved.\n5. Yes. Mean traced peak improved {ratio:.1f}× in the integration smoke test.\n6. Yes. Candidate latency remained acceptable at {perf['integrated_mean_candidate_ms']:.2f} ms mean.\n7. Yes. Permanent fixtures now include dense, repeated-term, zero, degenerate, tie-heavy, near-tie, TG-4Q, and TG-4S states.\n8. A default decision still needs broader independent evidence, especially dense and repeated-term discovery workloads rather than candidate-only fixtures.\n\n## Recommended TG-4V milestone\n\nRun one preregistered default-provider decision study with dense, repeated-term, and larger independent target coverage. Do not change the exhaustive default automatically.\n""";(a.output/'report.md').write_text(report);Path('docs/tensor_game_streaming_integration.md').write_text(report);print(json.dumps(summary,indent=2))
